let a = 0n;
let b = 1n;
for (let i = 0; i < n; i++) {
  const next = a + b;
  a = b;
  b = next;
}
return a;

if (!Number.isSafeInteger(n) || n < 0) throw new Error("n must be a non-negative safe integer");
let a = 0n;
let b = 1n;
let bit = 1;
while (bit <= n / 2) bit *= 2;
for (; bit > 0; bit = Math.floor(bit / 2)) {
  const c = a * ((b << 1n) - a);
  const d = a * a + b * b;
  if (Math.floor(n / bit) % 2 === 0) {
    a = c;
    b = d;
  } else {
    a = d;
    b = c + d;
  }
}
return a;

if (!Number.isInteger(n) || n < -90 || n > 90) {
  throw new Error("n must be an integer from -90 to 90");
}
const magnitude = Math.abs(n);
let previous = 0n;
let current = 1n;
for (let i = 0; i < magnitude; i++) {
  [previous, current] = [current, previous + current];
}
return n < 0 && magnitude % 2 === 0 ? -previous : previous;

